def run_case(t: object, holder: object, spec: dict, reached: set) -> dict:
    """One case against `holder`'s function, in a fresh test-owned tree; every launcher seam the command reads wrapped on `t`, recorded."""
    import contextlib, os, shutil, tempfile
    from pathlib import Path as _P
    transcript: list = []
    calls: list = []
    script = list(spec.get("answers", []))
    tmp = _P(tempfile.mkdtemp(prefix="syrd423-")).resolve()

    def norm(value):
        if isinstance(value, (list, tuple)):
            return [norm(v) for v in value]
        if isinstance(value, (set, frozenset)):
            return sorted(norm(v) for v in value)
        if isinstance(value, dict):
            return {str(k): norm(v) for k, v in sorted(value.items(), key=lambda kv: str(kv[0]))}
        if isinstance(value, _P):
            return "PATH " + norm(str(value))
        if isinstance(value, str):
            return value.replace(str(tmp), "TMP")
        if isinstance(value, (int, float, bool)) or value is None:
            return value
        kind = type(value).__name__
        if kind == "Field":
            return {kind: f"{value.name}: {value.title}"}
        if kind == "Choice":
            return {kind: value.value}
        if kind == "ProjectDesignArtifact":
            return {kind: norm(dict(vars(value)))}
        if callable(value):
            return "CALLABLE"
        return repr(value)

    def note(seam, /, *args, **kwargs):
        reached.add(seam)
        calls.append([seam, norm(list(args)), norm(dict(kwargs))])

    def ask(prompt):
        transcript.append(["ask", norm(prompt)])
        if len(transcript) > 400:
            raise AssertionError("the prompt did not stop asking")
        if not script and spec.get("eof"):
            raise EOFError
        answer = script.pop(0) if script else ""
        return str(tmp) + answer[1:] if answer.startswith("@/") else answer

    def show(line):
        transcript.append(["show", norm(line)])

    class Stdout:
        def write(self, text):
            if text.strip():
                transcript.append(["stdout", norm(text.rstrip("\n"))])
            return len(text)

        def flush(self):
            pass

    class Recorded:
        """A module read through the launcher, its functions recorded as they are called."""

        def __init__(self, name, real):
            self._name, self._real = name, real

        def __getattr__(self, attr):
            value = getattr(self._real, attr)
            if callable(value) and not isinstance(value, type):
                def wrapped(*args, _attr=attr, _value=value, **kwargs):
                    note(f"{self._name}.{_attr}", *args, **kwargs)
                    return _value(*args, **kwargs)
                return wrapped
            return value

    def place(value):
        if isinstance(value, str) and value.startswith("@/"):
            return tmp / value[2:]
        if isinstance(value, str) and value.startswith("rel:"):
            return _P(value[4:])
        return value

    seams = ("_validate_project_slug", "_prompt_text", "_prompt_bool", "_owner_user_verbatim", "validate_ticket_prefix", "_dedupe_role_names",
             "_validate_new_project_audit_role", "_default_role_cli_pairs", "_default_new_project_owner", "ProjectDesignArtifact",
             "project_design_artifact_payload", "_write_json_atomic", "_project_design_markdown", "Field", "Choice")
    names = [*FUNCTIONS, *seams, "terminal_select", "WORKTREE_POLICIES", "PROJECT_DESIGN_DEFAULT_GATES", "DEFAULT_PROJECT_IMPLEMENTER_ROLES"]
    saved = {n: getattr(t, n) for n in names}
    cwd = os.getcwd()
    try:
        (tmp / "repo").mkdir()
        (tmp / "cwd").mkdir()
        os.chdir(tmp / "cwd")
        under = {n: getattr(holder, n) for n in FUNCTIONS}
        on_launcher = {}
        for n in (*FUNCTIONS, *seams):
            def passthrough(*args, _n=n, **kwargs):
                note(_n, *args, **kwargs)
                return saved[_n](*args, **kwargs)
            on_launcher[n] = passthrough
        on_launcher["terminal_select"] = Recorded("terminal_select", saved["terminal_select"])
        on_launcher.update(spec.get("launcher", {}))
        for n, f in on_launcher.items():
            setattr(t, n, f)
        call = spec["call"]
        try:
            with contextlib.redirect_stdout(Stdout()):
                if call == "design":
                    kwargs = {k: place(v) for k, v in spec.get("args", {}).items()}
                    if "output_dir" in spec:
                        if spec["output_dir"] is not None:
                            kwargs["output_dir"] = place(spec["output_dir"]) if spec["output_dir"].startswith("@/") else _P(spec["output_dir"])
                    else:
                        kwargs["output_dir"] = tmp / "out"
                    got = under["design_project_command"](spec.get("project", "porter"), input_func=ask, print_func=show, **kwargs)
                elif call == "main":
                    got = t.main([str(tmp) + a[1:] if a.startswith("@/") else a for a in spec["argv"]])
                elif call == "comma":
                    got = under["_comma_list"](spec["value"])
                elif call == "artifact_path":
                    got = under["_default_project_artifact_path"]("porter", tmp / "d")
                else:
                    got = under["_default_project_design_document_path"]("porter", tmp / "d")
            answer = norm(got)
        except AssertionError:
            raise
        except BaseException as exc:  # noqa: BLE001 -- the baseline's own answer, whatever it raises
            answer = {"raised": type(exc).__name__, "message": norm(str(exc))}
        files = {}
        for path in sorted(tmp.rglob("*")):
            if path.is_file():
                # The artifact writer sets its own mode; anything else is left to the umask, which is not the command's.
                mode = oct(path.stat().st_mode & 0o777) if path.suffix == ".json" else "per umask"
                files[norm(str(path))] = [mode, norm(path.read_text(encoding="utf-8"))]
            elif not any(path.iterdir()):
                files[norm(str(path))] = "empty directory"
        return {"answer": answer, "transcript": transcript, "calls": calls, "files": files, "unused answers": script}
    finally:
        os.chdir(cwd)
        for n, f in saved.items():
            setattr(t, n, f)
        shutil.rmtree(tmp)
