def test_the_rules_hold_in_the_measured_record() -> None:
    def answer(label):
        return GOLDEN[label]["answer"]

    def artifact(label):
        return json.loads(next(entry[1] for f, entry in GOLDEN[label]["files"].items() if f.endswith(".json")))

    asks = [x[1] for x in GOLDEN["design: every question asked, every default taken"]["transcript"] if x[0] == "ask"]
    check(asks == ["Design document title [porter design]: ", "Design summary: ", "Code location: ", "Remote [origin]: ", "Default branch [main]: ",
                   "Worktree policy [shared]: ", "Owner user [porter-agent]: ", "Ticket prefix [PORTER]: ", "Push policy [director-main-only]: ",
                   "Require audit signoff gate [Y/n]: ", "Enable inspection gate by default [y/N]: ", "Enable user signoff gate by default [y/N]: ",
                   "Grant board-service traversal into the owner home [Y/n]: ", "Supplementary groups (comma-separated, blank for none): ",
                   "Enable linger for the owner user [Y/n]: ", "Owner shell [fish]: "], f"every question, in order, with its default: {asks}")
    check(answer("design: every argument given") == 0 and not [x for x in GOLDEN["design: every argument given"]["transcript"] if x[0] == "ask"],
          "every argument given: nothing is asked")
    files = GOLDEN["design: every argument given"]["files"]
    check(files["TMP/out/porter.project.json"][0] == "0o600" and files["TMP/out/porter-design.md"][1] == "# Porter\n\nA small coordination tool.\n",
          "the artifact is written owner-only, the document beside it")
    check(set(GOLDEN["design: no output directory: the working directory"]["files"]) >= {"TMP/cwd/porter.project.json", "TMP/cwd/porter-design.md"},
          "no output directory: the working directory")
    check(set(GOLDEN["design: an explicit artifact, the document beside it"]["files"]) >= {"TMP/elsewhere/p.json", "TMP/elsewhere/porter-design.md"},
          "the design document defaults to beside the artifact")
    check(answer("design: an auditor that is also an implementer")["message"] == "roles cannot be both implementers and auditors: review"
          and answer("design: a worktree policy nobody offers")["message"] == "worktree policy must be one of ['isolated', 'shared']"
          and answer("design: a blank owner")["message"] == "switchyard: owner user cannot be empty",
          "the refusals, word for word")
    for label in ("design: an auditor that is also an implementer", "design: a worktree policy nobody offers", "design: a dashed slug"):
        check(not [f for f in GOLDEN[label]["files"] if f.startswith("TMP/out/")], f"{label}: nothing written")
    check(artifact("design: an owner kept verbatim")["project"]["owner_user"] == "  Mixed.Case-owner  ".strip(), "the owner is taken verbatim (trimmed only)")
    check(artifact("design: every question asked and answered")["project"]["capability_grants"]["supplementary_groups"] == ["kvm", "video"],
          "a comma list with blanks gives just the names")
    check(artifact("design: a blank title and summary") is not None
          and GOLDEN["design: a blank title and summary"]["files"]["TMP/out/porter-design.md"][1] == "# porter design\n\nTBD.\n", "blank answers take the defaults")


def test_every_launcher_seam_is_reached() -> None:
    # Functions and types are wrapped on the launcher, and the selector module is recorded attribute by attribute; the
    # constants are rebound there by their own cases, except KIND_SINGLE, which every recorded Field call shows in use.
    names = {name for reads in SEAMS.values() for name in reads}
    modules = {name for name in names if type(getattr(t, name)).__name__ == "module"}
    expected = {name for name in names if callable(getattr(t, name))}
    check(expected <= REACHED, f"a recorder on the launcher reached every function and type: missing {sorted(expected - REACHED)}")
    check(all(any(r.startswith(f"{name}.") for r in REACHED) for name in modules) and modules == {"terminal_select"},
          f"and the selector module: {sorted(modules)}")
    rebound = {name for spec in CASES.values() for name in spec.get("launcher", {})}
    kinds = {c[2].get("kind") for v in GOLDEN.values() for c in v["calls"] if c[0] == "Field"}
    check(names - expected - modules == rebound | {"KIND_SINGLE"} and kinds == {"single"}, f"and every constant: {sorted(names - expected - modules)} {kinds}")


STRUCTURE = ("test_the_module_loads_no_other_switchyard_module_at_import", "test_either_import_order_gives_one_set_of_objects_and_the_defaults",
             "test_the_seams_read_through_the_launcher_and_nothing_bound", "test_the_launcher_reexports_the_four_and_main_reaches_them_there")
LAST = ("test_every_launcher_seam_is_reached",)


def main() -> int:
    names = sorted(name for name, value in globals().items() if name.startswith("test_") and callable(value))
    for name in [*STRUCTURE, *(name for name in names if name not in STRUCTURE + LAST), *LAST]:
        globals()[name]()
    print(f"project_design_command_boundary_test: {CHECKS} checks ok")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
